CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_members(project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('owner','editor','reviewer','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name text NOT NULL,head_revision_id uuid NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE CASCADE,parent_revision_id uuid NULL REFERENCES revisions(id),author_id uuid NOT NULL REFERENCES users(id),message text NOT NULL,document jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE branches DROP CONSTRAINT IF EXISTS branches_head_revision_fk;
ALTER TABLE branches ADD CONSTRAINT branches_head_revision_fk FOREIGN KEY(head_revision_id) REFERENCES revisions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX IF NOT EXISTS revisions_branch_created_idx ON revisions(branch_id,created_at DESC);
CREATE TABLE IF NOT EXISTS reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','approved','changes_requested','closed')),title text NOT NULL,body text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,submitted_by uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN('math.evaluate','build','test','file.validate')),input jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','cancelled')),output jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz);
CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs(status,created_at) WHERE status='queued';
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),project_id uuid REFERENCES projects(id) ON DELETE SET NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
